routes.handlerPolicy:
router.get(
    '/',
    requirePermission('read:users'),
    validate({ query: listUsersQuerySchema }),
    controller.list.bind(controller),
);

router.get(
    '/:id',
    requirePermission('read:users'),
    validate({ params: userIdParamSchema }),
    controller.getById.bind(controller),
);

router.post(
    '/',
    requirePermission('create:users'),
    validate({ body: createUserSchema }),
    controller.create.bind(controller),
);

router.put(
    '/:id',
    requirePermission('update:users'),
    validate({ params: userIdParamSchema, body: updateUserSchema }),
    controller.update.bind(controller),
);

router.delete(
    '/:id',
    requirePermission('delete:users'),
    validate({ params: userIdParamSchema }),
    controller.delete.bind(controller),
);

router.post(
    '/',
    requirePermission('create:roles'),
    validate({ body: createRoleSchema }),
    controller.create.bind(controller),
);

router.put(
    '/:id/permissions',
    requirePermission('update:roles'),
    validate({ params: roleIdParamSchema, body: updateRolePermissionsSchema }),
    controller.updatePermissions.bind(controller),
);

router.post(
    '/customers/:id/interactions',
    requirePermission('manage:crm'),
    validate({ body: createInteractionSchema }),
    CrmController.addInteraction
);
